    def __init__(self):
        self.routes = []

    def add(self, method, template, name):
        pass

    def match(self, method, path):
        return (404, None, {})

solution.solution.py:
from urllib.parse import unquote


class Router:
    def __init__(self):
        self.routes = []

    def add(self, method, template, name):
        self.routes.append((method.upper(), self._split(template), name))

    @staticmethod
    def _split(path):
        path = path.split("?", 1)[0]
        if len(path) > 1 and path.endswith("/"):
            path = path[:-1]
        return path.strip("/").split("/") if path.strip("/") else []

    def match(self, method, path):
        parts = self._split(path)
        path_matched = False
        for route_method, segments, name in self.routes:
            if len(segments) != len(parts):
                continue
            params = {}
            ok = True
            for seg, part in zip(segments, parts):
                if seg.startswith("{") and seg.endswith("}"):
                    if not part:
                        ok = False
                        break
                    params[seg[1:-1]] = unquote(part)
                elif seg != part:
                    ok = False
                    break
            if not ok:
                continue
            path_matched = True
            if route_method == method.upper():
                return (200, name, params)
        return (405, None, {}) if path_matched else (404, None, {})
